export type IconName = keyof typeof ICONS;

export function Icon({
 name,
 size = 20
}: {
 name: IconName;
 size?: number;
}) {
 const def = ICONS[name];
 return (
 <svg
 className="lab-icon"
 width={size}
 height={size}
 viewBox={`0 0 ${def.box} ${def.box}`}
 fill="currentColor"
 aria-hidden="true"
 focusable="false"
 >
 <path d={def.d} />
 </svg>
 );
}
