 src: url(/aiux/assets/core/fonts/ServiceNowSans-Light.woff2) format("woff2");
}
@font-face {
 font-family: "ServiceNow Sans";
 font-weight: 400;
 font-style: normal;
 font-display: swap;
 src: url(/aiux/assets/core/fonts/ServiceNowSans-Regular.woff2) format("woff2");
}
@font-face {
 font-family: "ServiceNow Sans";
 font-weight: 500;
 font-style: normal;
 font-display: swap;
 src: url(/aiux/assets/core/fonts/ServiceNowSans-Medium.woff2) format("woff2");
}
@font-face {
 font-family: "ServiceNow Sans";
 font-weight: 600;
 font-style: normal;
 font-display: swap;
 src: url(/aiux/assets/core/fonts/ServiceNowSans-Bold.woff2) format("woff2");
}
@font-face {
 font-family: "ServiceNow Sans";
 font-weight: 700;
 font-style: normal;
 font-display: swap;
 src: url(/aiux/assets/core/fonts/ServiceNowSans-Bold.woff2) format("woff2");
}

/* ---------------------------------------------------------------------------
 * AIUX theme. primary / accent / neutral / radii are the exact values from the
 * wdf-lab AppTheme (theme.js) and the experience themeData. The intermediate
 * neutral steps are generated by the AIUX runtime in the browser and are not
 * exposed server-side, so they are stepped from the same warm neutral base.
 * ------------------------------------------------------------------------- */
:root {
 --lab-primary: #032d42;
 --lab-primary-hover: #05415f;
 --lab-primary-soft: #e6edf1;
 --lab-accent: #63df4e;
 --lab-on-primary: #ffffff;

 /* Warm neutral shell, as in the AIUX experience: page, header and sidebar
 all sit on cream. Only cards, tables and images are white. */
 --lab-canvas: #edecea;
 --lab-shell: #efeeeb;
 --lab-surface: #ffffff;
 --lab-surface-2: #e6e5e1;
 --lab-active: #e3e2de;
 --lab-border: #dedcd6;
 --lab-border-strong: #c9c6bd;

 --lab-text: #16191c;
 --lab-text-secondary: #55595c;
 --lab-text-tertiary: #767a7e;

 --lab-positive: #167442;
 --lab-positive-soft: #e7f5ec;
 --lab-warning: #7a4d00;
 --lab-warning-soft: #fdf3e0;
 --lab-critical: #ab1f1f;
 --lab-critical-soft: #fdeded;

 --lab-radius-selector: 0.75rem;
 --lab-radius-field: 0.5rem;
 --lab-radius-box: 1rem;
 --lab-border-width: 1px;

 --lab-sidebar-w: 17rem;
 --lab-header-h: 3.5rem;

 --lab-font: "ServiceNow Sans";
}

/* ---------------------------------------------------------------------------
 * Reset + shell
 * ------------------------------------------------------------------------- */
html,
body {
 margin: 0;
 padding: 0;
 height: 100%;
 background: var(--lab-canvas);
}

.lab-app,
.lab-app * {
 font-family: var(--lab-font);
 box-sizing: border-box;
}

.lab-app {
 min-height: 100vh;
 color: var(--lab-text);
 background: var(--lab-canvas);
}

.lab-icon {
 display: block;
 flex: 0 0 auto;
}

/* Header ------------------------------------------------------------------ */
.lab-header {
 position: fixed;
 inset: 0 0 auto 0;
 height: var(--lab-header-h);
 display: flex;
 align-items: center;
 gap: 0.75rem;
 padding: 0 1rem;
 background: var(--lab-shell);
 z-index: 20;
}

.lab-logo {
 height: 1.5rem;
 width: auto;
 display: block;
 flex: 0 0 auto;
}

.lab-app-title {
 margin: 0;
 font-size: 0.9375rem;
 font-weight: 600;
 color: var(--lab-text);
 line-height: 1.25rem;
}

/* Sidebar ----------------------------------------------------------------- */
.lab-sidebar {
 position: fixed;
 top: var(--lab-header-h);
 bottom: 0;
 left: 0;
 width: var(--lab-sidebar-w);
 overflow-y: auto;
 background: var(--lab-shell);
 padding: 0.75rem 0.5rem 2rem;
 z-index: 10;
}

.lab-nav {
 margin: 0;
 padding: 0;
 list-style: none;
 display: flex;
 flex-direction: column;
 gap: 0.125rem;
}

.lab-nav-divider {
 height: var(--lab-border-width);
 background: var(--lab-border);
 margin: 0.5rem 0.25rem;
}

.lab-nav-btn {
 width: 100%;
 display: flex;
 align-items: center;
 gap: 0.625rem;
 padding: 0.5rem 0.625rem;
 border: 0;
 border-radius: var(--lab-radius-field);
 background: transparent;
 color: var(--lab-text-secondary);
 font-size: 0.875rem;
 font-weight: 500;
 line-height: 1.25rem;
 text-align: left;
 cursor: pointer;
}

.lab-nav-btn:hover {
 background: var(--lab-surface-2);
 color: var(--lab-text);
}

.lab-nav-btn.is-active {
 background: var(--lab-active);
 color: var(--lab-text);
 font-weight: 600;
}

.lab-nav-btn-label {
 flex: 1 1 auto;
 min-width: 0;
}

.lab-nav-caret {
 transition: transform 120ms ease;
 color: var(--lab-text-tertiary);
}

.lab-nav-caret.is-open {
 transform: rotate(90deg);
}

.lab-nav-l2 {
 margin: 0.125rem 0 0.25rem;
 padding: 0 0 0 0.75rem;
 list-style: none;
 display: flex;
 flex-direction: column;
 gap: 0.125rem;
 border-left: var(--lab-border-width) solid var(--lab-border);
 margin-left: 1.25rem;
}

.lab-nav-l2 .lab-nav-btn {
 font-size: 0.8125rem;
 font-weight: 400;
 padding: 0.375rem 0.5rem;
}

.lab-nav-l2 .lab-nav-btn.is-active {
 font-weight: 600;
}

/* Main -------------------------------------------------------------------- */
.lab-main {
 margin-left: var(--lab-sidebar-w);
 padding-top: var(--lab-header-h);
 min-height: 100vh;
}

.lab-page {
 max-width: 56rem;
 margin: 0 auto;
 padding: 1.5rem 1rem 4rem;
 display: flex;
 flex-direction: column;
 gap: 2rem;
}

@media (min-width: 64rem) {
 .lab-page {
 padding: 2rem 2rem 5rem;
 }
}

@media (max-width: 60rem) {
 .lab-sidebar {
 display: none;
 }
 .lab-main {
 margin-left: 0;
 }
}

/* Content ----------------------------------------------------------------- */
.lab-titleblock {
 display: flex;
 flex-direction: column;
 gap: 0.5rem;
}

.lab-h1 {
 margin: 0;
 font-size: 2.25rem;
 line-height: 2.5rem;
 font-weight: 700;
}

.lab-h2 {
 margin: 0;
 font-size: 1.875rem;
 line-height: 2.25rem;
 font-weight: 700;
}

.lab-h3 {
 margin: 0;
 font-size: 1.5rem;
 line-height: 2rem;
 font-weight: 600;
}

.lab-h4 {
 margin: 0;
 font-size: 1.125rem;
 line-height: 1.75rem;
 font-weight: 600;
 display: flex;
 flex-wrap: wrap;
 align-items: center;
 gap: 0.5rem;
}

.lab-p {
 margin: 0;
 font-size: 1rem;
 line-height: 1.625;
 color: var(--lab-text-secondary);
}

.lab-section {
 display: flex;
 flex-direction: column;
 gap: 1rem;
}

.lab-badges {
 display: flex;
 flex-wrap: wrap;
 gap: 0.5rem;
}

.lab-tag {
 display: inline-block;
 padding: 0.125rem 0.5rem;
 border-radius: 999px;
 border: var(--lab-border-width) solid transparent;
 font-size: 0.75rem;
 font-weight: 600;
 line-height: 1.25rem;
 white-space: nowrap;
}

.lab-tag--section {
 width: fit-content;
 color: var(--lab-primary);
 border-color: var(--lab-primary);
}

.lab-tag--level {
 color: var(--lab-positive);
 background: var(--lab-positive-soft);
}

.lab-tag--ghost {
 color: var(--lab-text-secondary);
 background: var(--lab-surface-2);
}

.lab-tag--note {
 color: var(--lab-warning);
 background: var(--lab-warning-soft);
}

.lab-tag--critical {
 color: var(--lab-critical);
 background: var(--lab-critical-soft);
}

.lab-steps {
 margin: 0;
 padding-left: 1.5rem;
 list-style-type: decimal;
 display: flex;
 flex-direction: column;
 gap: 1rem;
 font-size: 1rem;
 color: var(--lab-text-secondary);
}

.lab-step {
 line-height: 1.625;
}

.lab-step-body {
 display: inline;
}

.lab-step-body .lab-tag {
 margin-right: 0.5rem;
}

.lab-figure {
 margin: 0;
}

.lab-figure--step {
 margin-top: 0.5rem;
}

.lab-img {
 display: block;
 width: 100%;
 height: auto;
 border: var(--lab-border-width) solid var(--lab-border);
 border-radius: var(--lab-radius-selector);
 background: var(--lab-surface);
}

.lab-img--inline {
 width: auto;
 max-width: 32rem;
}

.lab-callout {
 padding: 1rem;
 border-radius: var(--lab-radius-selector);
 border: var(--lab-border-width) solid var(--lab-positive);
 background: var(--lab-positive-soft);
 color: var(--lab-text);
 font-size: 1rem;
 line-height: 1.625;
}

.lab-table {
 width: 100%;
 border-collapse: collapse;
 font-size: 0.9375rem;
 background: var(--lab-surface);
 border: var(--lab-border-width) solid var(--lab-border);
 border-radius: var(--lab-radius-selector);
 overflow: hidden;
}

.lab-table th,
.lab-table td {
 text-align: left;
 padding: 0.625rem 0.875rem;
 border-bottom: var(--lab-border-width) solid var(--lab-border);
}

.lab-table th {
 background: var(--lab-surface-2);
 font-weight: 600;
 color: var(--lab-text);
}

.lab-table td {
 color: var(--lab-text-secondary);
}

.lab-table tr:last-child td {
 border-bottom: 0;
}

.lab-action {
 width: fit-content;
 padding: 0.5rem 1rem;
 border-radius: var(--lab-radius-field);
 border: var(--lab-border-width) solid var(--lab-primary);
 font-size: 0.875rem;
 font-weight: 600;
 line-height: 1.25rem;
 text-decoration: none;
 cursor: pointer;
 background: transparent;
 color: var(--lab-primary);
}

.lab-action--primary {
 background: var(--lab-primary);
 color: var(--lab-on-primary);
}

.lab-action--primary:hover {
 background: var(--lab-primary-hover);
 border-color: var(--lab-primary-hover);
}

.lab-action--outline:hover {
 background: var(--lab-primary-soft);
}

.lab-action:focus-visible {
 outline: 2px solid var(--lab-primary);
 outline-offset: 2px;
}

/* prose ------------------------------------------------------------------ */
.lab-strong {
 color: var(--lab-text);
 font-weight: 600;
}

.lab-list {
 margin: 0;
 padding-left: 1.5rem;
 list-style-type: disc;
 display: flex;
 flex-direction: column;
 gap: 0.25rem;
 font-size: 1rem;
 line-height: 1.625;
 color: var(--lab-text-secondary);
}

.lab-list--ordered {
 list-style-type: decimal;
}

.lab-quote {
 margin: 0;
 padding: 0.75rem 1rem;
 border-left: 3px solid var(--lab-primary);
 background: var(--lab-surface-2);
 border-radius: 0 var(--lab-radius-field) var(--lab-radius-field) 0;
 font-size: 0.9375rem;
 line-height: 1.6;
 color: var(--lab-text-secondary);
}

.lab-link {
 color: var(--lab-primary);
 text-decoration: underline;
 text-underline-offset: 2px;
}

.lab-link:hover {
 color: var(--lab-primary-hover);
}

.lab-linkbtn {
 padding: 0;
 border: 0;
 background: none;
 font: inherit;
 color: var(--lab-primary);
 text-align: left;
 text-decoration: underline;
 text-underline-offset: 2px;
 cursor: pointer;
}

.lab-linkbtn:hover {
 color: var(--lab-primary-hover);
}

/* virtual-on animation frame --------------------------------------------- */
.lab-vo-frame {
 display: block;
 width: 100%;
 aspect-ratio: 16 / 9;
 border: var(--lab-border-width) solid var(--lab-border);
 border-radius: var(--lab-radius-selector);
 background: #080b0e;
}

/* fetched markdown ------------------------------------------------------- */
.lab-md {
 display: flex;
 flex-direction: column;
 gap: 1rem;
}

.lab-md > .lab-h2 {
 margin-top: 1rem;
}

.lab-md > .lab-h3 {
 margin-top: 0.75rem;
}

.lab-li > .lab-md,
.lab-li {
 line-height: 1.625;
}

.lab-li > p.lab-p:first-child {
 display: inline;
}

.lab-li .lab-figure {
 margin-top: 0.5rem;
}

.lab-li .lab-img {
 max-width: 32rem;
}

.lab-mark {
 background: transparent;
 color: inherit;
 font-weight: 600;
}

.lab-mark--critical {
 color: var(--lab-critical);
}

.lab-mark--warning {
 color: var(--lab-warning);
}

.lab-mark--positive {
 color: var(--lab-positive);
}

.lab-mark--info {
 color: var(--lab-primary);
}

.lab-code {
 padding: 0.0625rem 0.25rem;
 border-radius: 0.25rem;
 background: var(--lab-surface-2);
 border: var(--lab-border-width) solid var(--lab-border);
 font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
 font-size: 0.875em;
 color: var(--lab-text);
}

.lab-pre {
 margin: 0;
 padding: 0.875rem 1rem;
 overflow-x: auto;
 border-radius: var(--lab-radius-selector);
 background: var(--lab-surface);
 border: var(--lab-border-width) solid var(--lab-border);
 font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
 font-size: 0.8125rem;
 line-height: 1.5;
 color: var(--lab-text);
}

.lab-table-wrap {
 overflow-x: auto;
}

.lab-hr {
 width: 100%;
 height: var(--lab-border-width);
 margin: 0.5rem 0;
 border: 0;
 background: var(--lab-border);
}

.lab-loading {
 padding: 2rem;
 color: var(--lab-text-tertiary);
 font-size: 0.9375rem;
}

/* placeholder ----------------------------------------------------------- */
.lab-placeholder {
 padding: 2rem;
 border: var(--lab-border-width) dashed var(--lab-border-strong);
 border-radius: var(--lab-radius-box);
 background: var(--lab-surface);
 color: var(--lab-text-secondary);
 font-size: 1rem;
 line-height: 1.625;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React from "react";
